CHECKERS = []   # (item_type, frame, function, igvfd_file)
_CURRENT_FILE = [""]


class AuditFailure(Exception):
    """snovault.auditor.AuditFailure: category, detail, level."""

    def __init__(self, category, detail=None, level=0, path=None, name=None):
        super().__init__(detail)
        self.category = category
        self.detail = detail
        self.level = level
        self.path = path
        self.name = name


def audit_checker(item_type, frame="embedded", condition=None):
    """snovault.auditor.audit_checker: register the function for a type."""
    def deco(fn):
        CHECKERS.append((item_type, frame, fn, _CURRENT_FILE[0], condition))
        return fn
    return deco


def watch_for_changes_in(functions=None, **kwargs):
    """snovault.mapping.watch_for_changes_in: indexing hint, no-op here."""
    def deco(fn):
        return fn
    return deco


def simple_path_ids(obj, path):
    """snovault.util.simple_path_ids: the ids at a dotted path in an object."""
    if isinstance(path, str):
        path = path.split(".")
    if not path:
        yield obj
        return
    name, rest = path[0], path[1:]
    value = obj.get(name, None) if isinstance(obj, dict) else None
    if not isinstance(value, list):
        value = [value]
    for member in value:
        if member is None:
            continue
        yield from simple_path_ids(member, rest)


