# igvfd/audit/file_set.py:audit_file_set_files_missing_analysis_step_version @ cb8fb4a
def audit_file_set_files_missing_analysis_step_version(value, system):
    '''
    [
        {
            "audit_description": "Analysis set, prediction set, and pseudobulk set files are expected to specify analysis step version.",
            "audit_category": "missing analysis step version",
            "audit_level": "NOT_COMPLIANT"
        },
        {
            "audit_description": "Model set files are expected to specify analysis step version.",
            "audit_category": "missing analysis step version",
            "audit_level": "WARNING"
        }
    ]
    '''
    object_type = space_in_words(value['@type'][0]).capitalize()
    audit_message_analysis_prediction = get_audit_message(audit_file_set_files_missing_analysis_step_version, index=0)
    audit_message_model = get_audit_message(audit_file_set_files_missing_analysis_step_version, index=1)
    if object_type == 'Model set':
        audit_message = audit_message_model
    else:
        audit_message = audit_message_analysis_prediction
    files = value.get('files')
    files_with_missing_asv = []
    for file in files:
        file_object = system.get('request').embed(file + '@@object?skip_calculated=true')
        if file_object.get('derived_manually') is True:
            continue
        else:
            if not (file_object.get('analysis_step_version', '')):
                files_with_missing_asv.append(file)
    if files_with_missing_asv:
        files_with_missing_asv = ', '.join([audit_link(path_to_text(file), file) for file in files_with_missing_asv])
        detail = (
            f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} '
            f'links to file(s) {files_with_missing_asv} that are missing `analysis_step_version`.'
        )
        yield AuditFailure(audit_message.get('audit_category', ''), f'{detail} {audit_message.get("audit_description", "")}', level=audit_message.get('audit_level', ''))


# igvfd/audit/file_set.py:audit_input_file_sets_derived_from @ cb8fb4a
def audit_input_file_sets_derived_from(value, system):
    '''
    [
        {
            "audit_description": "The file sets of the files that are used to derive the files in this file set are expected to be listed in the input file sets.",
            "audit_category": "missing input file set",
            "audit_level": "ERROR"
        },
        {
            "audit_description": "Files in an analysis set or pseudobulk set are expected to be derived from other files.",
            "audit_category": "missing derived from",
            "audit_level": "NOT_COMPLIANT"
        },
        {
            "audit_description": "Files in prediction sets and model sets are expected to be derived from other files.",
            "audit_category": "missing derived from",
            "audit_level": "WARNING"
        },
        {
            "audit_description": "The input files are expected to belong to the input file sets.",
            "audit_category": "unexpected input file set",
            "audit_level": "ERROR"
        }
    ]
    '''
    object_type = space_in_words(value['@type'][0]).capitalize()
    audit_message_missing_input_file_set = get_audit_message(audit_input_file_sets_derived_from, index=0)
    audit_message_missing_derived_from_analysis = get_audit_message(audit_input_file_sets_derived_from, index=1)
    audit_message_missing_derived_from_prediction_model = get_audit_message(audit_input_file_sets_derived_from, index=2)
    audit_message_unexpected_input_file_set = get_audit_message(audit_input_file_sets_derived_from, index=3)
    detail = ''
    input_file_sets = value.get('input_file_sets', [])
    files = value.get('files', [])
    files_to_link = []
    derived_from_files_to_link = []
    missing_derived_from_file_sets = []
    missing_derived_from = []
    all_derived_from_file_sets = []
    preferred_assay_titles = value.get('preferred_assay_titles', [])
    exclude_assays = {
        'Cell painting',
        'Variant painting via fluorescence',
        'Variant painting via immunostaining'
    }
    exclude_file_content_types = {
        'marker genes'
    }
    # Skip audit if it is an imaging assay
    if any(assay in exclude_assays for assay in preferred_assay_titles):
        return
    if files:
        for file in files:
            file_object = system.get('request').embed(file + '@@object?skip_calculated=true')
            derived_from_files = file_object.get('derived_from', [])
            if derived_from_files:
                for derived_from_file in derived_from_files:
                    derived_from_file_object = system.get('request').embed(
                        derived_from_file + '@@object?skip_calculated=true')
                    derived_from_file_set = derived_from_file_object['file_set']
                    all_derived_from_file_sets.append(derived_from_file_set)
                    if derived_from_file_set not in input_file_sets and derived_from_file_set != value['@id']:
                        files_to_link.append(file)
                        derived_from_files_to_link.append(derived_from_file)
                        missing_derived_from_file_sets.append(derived_from_file_set)
            else:
                if file_object.get('content_type') not in exclude_file_content_types:
                    missing_derived_from.append(file)
    if missing_derived_from_file_sets:
        files_to_link = ', '.join([audit_link(path_to_text(file), file) for file in set(files_to_link)])
        derived_from_files_to_link = ', '.join([audit_link(path_to_text(file), file)
                                               for file in set(derived_from_files_to_link)])
        missing_derived_from_file_sets = list(set(missing_derived_from_file_sets))
        missing_derived_from_file_sets = ', '.join(
            [audit_link(path_to_text(file_set), file_set) for file_set in missing_derived_from_file_sets])
        detail = (
            f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} '
            f'links to file(s) {files_to_link} that are `derived_from` '
            f'file(s) {derived_from_files_to_link} from file set(s) {missing_derived_from_file_sets} '
            f'which are not in `input_file_sets`.'
        )
        yield AuditFailure(audit_message_missing_input_file_set.get('audit_category', ''), f'{detail} {audit_message_missing_input_file_set.get("audit_description", "")}', level=audit_message_missing_input_file_set.get('audit_level', ''))
    if missing_derived_from:
        if object_type in ['Analysis set', 'Pseudobulk set']:
            audit_message_missing_derived_from = audit_message_missing_derived_from_analysis
        else:
            audit_message_missing_derived_from = audit_message_missing_derived_from_prediction_model
        missing_derived_from = ', '.join([audit_link(path_to_text(file), file) for file in missing_derived_from])
        detail = (
            f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} '
            f'links to file(s) {missing_derived_from} that have no `derived_from`.'
        )
        yield AuditFailure(audit_message_missing_derived_from.get('audit_category', ''), f'{detail} {audit_message_missing_derived_from.get("audit_description", "")}', level=audit_message_missing_derived_from.get('audit_level', ''))
    unexpected_file_sets = list(set(input_file_sets) - set(all_derived_from_file_sets))
    if unexpected_file_sets:
        unexpected_file_sets = ', '.join(
            [audit_link(path_to_text(file_set), file_set) for file_set in unexpected_file_sets])
        detail = (
            f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} '
            f'links to file set(s): {unexpected_file_sets} in `input_file_sets` that are not represented in the '
            f'`derived_from` of the file sets of the files in this analysis.'
        )
        yield AuditFailure(audit_message_unexpected_input_file_set.get('audit_category', ''), f'{detail} {audit_message_unexpected_input_file_set.get("audit_description", "")}', level=audit_message_unexpected_input_file_set.get('audit_level', ''))


# igvfd/audit/file_set.py:audit_file_set_missing_description @ cb8fb4a
def audit_file_set_missing_description(value, system):
    '''
    [
        {
            "audit_description": "Principal analysis sets, prediction sets, and model sets are expected to have descriptions summarizing the experiment or predictive model they are associated with.",
            "audit_category": "missing description",
            "audit_level": "NOT_COMPLIANT"
        },
        {
            "audit_description": "Construct library sets that are either reporter library or guide library are expected to have descriptions summarizing the experiment they are associated with.",
            "audit_category": "missing description",
            "audit_level": "NOT_COMPLIANT"
        }
    ]
    '''
    object_type = space_in_words(value['@type'][0]).capitalize()
    audit_message_general = get_audit_message(audit_file_set_missing_description, index=0)
    audit_message_cls = get_audit_message(audit_file_set_missing_description, index=1)
    file_set_type = value.get('file_set_type')

    if value.get('description'):
        return

    if value.get('@type')[0] == 'ConstructLibrarySet':
        if file_set_type not in ['reporter library', 'guide library']:
            return
        detail = (
            f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} is a {file_set_type}'
            f' and has no `description`.'
        )
        yield AuditFailure(audit_message_cls.get('audit_category', ''), f'{detail} {audit_message_cls.get("audit_description", "")}', level=audit_message_cls.get('audit_level', ''))
    elif file_set_type != 'intermediate analysis':
        detail = (
            f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} '
            f'has no `description`.'
        )
        yield AuditFailure(audit_message_general.get('audit_category', ''), f'{detail} {audit_message_general.get("audit_description", "")}', level=audit_message_general.get('audit_level', ''))


# igvfd/audit/file_set.py:audit_missing_genome_transcriptome_references @ cb8fb4a
def audit_missing_genome_transcriptome_references(value, system):
    '''
    [
        {
            "audit_description": "Files processed from transcript sequence data are expected to link to a transcriptome reference.",
            "audit_category": "missing reference files",
            "audit_level": "NOT_COMPLIANT"
        },
        {
            "audit_description": "Files that contain genomic coordinates or refer to variants are expected to link to a genome reference.",
            "audit_category": "missing reference files",
            "audit_level": "NOT_COMPLIANT"
        },
        {
            "audit_description": "Tabular files processed from transcript sequence data are expected to link to a transcriptome reference.",
            "audit_category": "missing reference files",
            "audit_level": "INTERNAL_ACTION"
        },
        {
            "audit_description": "Tabular files that contain genomic coordinates or refer to variants are expected to link to a genome reference.",
            "audit_category": "missing reference files",
            "audit_level": "INTERNAL_ACTION"
        },
        {
            "audit_description": "Tabular files in prediction sets that contain genomic coordinates are expected to link to a genome reference.",
            "audit_category": "missing reference files",
            "audit_level": "INTERNAL_ACTION"
        },
        {
            "audit_description": "Tabular files in prediction sets that contain transcript identifiers are expected to link to a transcriptome reference.",
            "audit_category": "missing reference files",
            "audit_level": "INTERNAL_ACTION"
        }
    ]
    '''
    object_type = space_in_words(value['@type'][0]).capitalize()
    audit_message_transcriptome = get_audit_message(audit_missing_genome_transcriptome_references, index=0)
    audit_message_genome = get_audit_message(audit_missing_genome_transcriptome_references, index=1)
    audit_message_transcriptome_tabular = get_audit_message(audit_missing_genome_transcriptome_references, index=2)
    audit_message_genome_tabular = get_audit_message(audit_missing_genome_transcriptome_references, index=3)
    audit_message_prediction_genome = get_audit_message(audit_missing_genome_transcriptome_references, index=4)
    audit_message_prediction_transcriptome = get_audit_message(audit_missing_genome_transcriptome_references, index=5)
    files = value.get('files', [])
    files_missing_genome = []  # List of files missing genome reference
    files_missing_transcriptome = []   # List of files missing transcriptome reference
    tabular_files_missing_genome = []  # List of tabular files missing genome reference
    tabular_files_missing_transcriptome = []   # List of tabular files missing transcriptome reference

    # Content types requiring genome reference for prediction sets (all are tabular files so far)
    prediction_genome_reference_content_types = [
        'aggregated calibrated coding variant effects',
        'calibrated coding variant effects',
        'disease level protein-protein interaction score',
        'element to gene interactions',
        'elements reference',
        'gene quantifications',
        'population level protein-protein interaction score',
        'protein–protein interaction disruption scores',
        'variant binding effects',
        'variant effects',
        'variant functions'
    ]

    # Content types requiring genome reference for prediction sets (all are tabular files so far)
    prediction_transcriptome_reference_content_types = [
        'calibrated coding variant effects',
        'aggregated calibrated coding variant effects',
        'coding variant effects',
        'disease level protein-protein interaction score',
        'gene quantifications',
        'machine learning model features',
        'population level protein-protein interaction score',
        'variant pathogenicity'
    ]

    excluded_content_types_tabular_files = [
        'aggregated pseudobulk quality report',
        'barcode onlist',
        'barcode replacement',
        'barcode to cluster mapping',
        'barcode to donor mapping',
        'barcode to element mapping',
        'barcode to hashtag mapping',
        'barcode to sample mapping',
        'barcode to variant mapping',
        'barcode to well mapping',
        'calibrated coding variant effect thresholds',
        'cell annotations',
        'cell annotation with TF overexpression',
        'cell hashing barcodes',
        'coding variant effects',
        'coding_variants',
        'complexes',
        'derived barcode mapping',
        'diseases_genes',
        'documentation (readme)',
        'drugs',
        'effective spatial variability',
        'external source data',
        'genes',
        'genes in pathways',
        'genes_genes',
        'genes_pathways',
        'genes_terms',
        'genome index',
        'genome reference',
        'genomic_elements',
        'genomic_elements_genes',
        'genomic_elements_genomic_elements',
        'go_terms_proteins',
        'heritability enrichment',
        'index plate',
        'individual cells profile',
        'machine learning model features',
        'marker gene activity',
        'marker genes',
        'motifs_proteins',
        'normalized variants profile',
        'ontology_terms',
        'pathogenicity validation',
        'pathways',
        'pathways_pathways',
        'per-barcode quality report',
        'per-cell quality report',
        'pipeline parameters',
        'post-segmentation transcript and cell locations',
        'predicted gene regulatory networks',
        'primer sequences',
        'protein sequences',
        'protein stability fluorescence score',
        'protein to protein interaction score',
        'proteins_proteins',
        'pseudobulk annotations',
        'pseudobulk barcode list',
        'sample sort parameters',
        'spatial transcriptomics cell metadata',
        'spatial transcriptomics slide-level cell boundaries',
        'spatial transcriptomics slide-level cell coordinates',
        'spatial transcriptomics slide-level transcripts',
        'studies_variants_phenotypes',
        'tissue positions',
        'transcriptome index',
        'transcriptome reference',
        'variants_diseases',
        'variants_drugs',
        'variants_genes',
        'variants_genomic_elements',
        'variants_proteins',
        'variants_proteins_terms',
        'variants_variants'
    ]
    excluded_content_types_alignment_files = ['methylated reads']
    if value.get('file_set_type', '') == 'external data for catalog':
        return

    # Handle Prediction Set separately
    if 'PredictionSet' in value.get('@type', []):
        prediction_tabular_files_missing_genome = []
        prediction_tabular_files_missing_transcriptome = []

        if files:
            for file in files:
                file_obj = system.get('request').embed(file + '@@object?skip_calculated=true')
                content_type = file_obj.get('content_type', '')

                if content_type in prediction_genome_reference_content_types:
                    has_genome_reference = check_genome_or_transcriptome_reference(file, system, 'genome')
                    if not has_genome_reference:
                        prediction_tabular_files_missing_genome.append(file)

                if content_type in prediction_transcriptome_reference_content_types:
                    has_transcriptome_reference = check_genome_or_transcriptome_reference(file, system, 'transcriptome')
                    if not has_transcriptome_reference:
                        prediction_tabular_files_missing_transcriptome.append(file)

        # Audit for missing genome references in prediction sets
        if prediction_tabular_files_missing_genome:
            prediction_tabular_files_missing_genome = join_obj_paths(
                data_object_paths=prediction_tabular_files_missing_genome)
            detail = (
                f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} '
                f'has tabular file(s) with no genome `reference_files`: {prediction_tabular_files_missing_genome}.'
            )
            yield AuditFailure(audit_message_prediction_genome.get('audit_category', ''), f'{detail} {audit_message_prediction_genome.get("audit_description", "")}', level=audit_message_prediction_genome.get('audit_level', ''))

        # Audit for missing transcriptome references in prediction sets
        if prediction_tabular_files_missing_transcriptome:
            prediction_tabular_files_missing_transcriptome = join_obj_paths(
                data_object_paths=prediction_tabular_files_missing_transcriptome)
            detail = (
                f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} '
                f'has tabular file(s) with no transcriptome `reference_files`: {prediction_tabular_files_missing_transcriptome}.'
            )
            yield AuditFailure(audit_message_prediction_transcriptome.get('audit_category', ''), f'{detail} {audit_message_prediction_transcriptome.get("audit_description", "")}', level=audit_message_prediction_transcriptome.get('audit_level', ''))
        return

    if files:
        for file in files:
            if not file.startswith(('/alignment-files/', '/matrix-files/', '/signal-files/', '/tabular-files/')):
                continue
            # Skip tabular files with certain excluded content_types.
            if file.startswith('/tabular-files/'):
                file_obj = system.get('request').embed(file + '@@object?skip_calculated=true')
                if file_obj['content_type'] in excluded_content_types_tabular_files:
                    continue
            # Skip alignment files with certain excluded content_types.
            if file.startswith('/alignment-files/'):
                file_obj = system.get('request').embed(file + '@@object?skip_calculated=true')
                if file_obj['content_type'] in excluded_content_types_alignment_files:
                    continue
            # Get all upstream Seqfiles that eventually lead to data file
            # and check if upstream seqfiles are transcriptome based assays
            is_transcriptome_assay = any(
                check_transcriptome_assay(seq_file, system)
                for seq_file in yield_all_upstream_seqfiles(file, system)
            )
            # Check for genome reference.
            has_genome_reference = check_genome_or_transcriptome_reference(file, system, 'genome')
            # Check if the data file under the Analysis Set has a transcriptome reference
            has_transcriptome_reference = check_genome_or_transcriptome_reference(file, system, 'transcriptome')

            if not is_transcriptome_assay and not has_genome_reference:
                if file.startswith('/tabular-files/'):
                    tabular_files_missing_genome.append(file)
                else:
                    files_missing_genome.append(file)
            # If a transcriptome seqfile doesn't have transcriptome reference, add it to the list
            if is_transcriptome_assay and not has_transcriptome_reference:
                if file.startswith('/tabular-files/'):
                    tabular_files_missing_transcriptome.append(file)
                else:
                    files_missing_transcriptome.append(file)
    # Audit 1: if there are transcriptome based analysis files missing transcriptome references
    if files_missing_transcriptome:
        files_missing_transcriptome = join_obj_paths(data_object_paths=files_missing_transcriptome)
        detail = (
            f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} '
            f'has file(s) with no transcriptome `reference_files`: {files_missing_transcriptome}.'
        )
        yield AuditFailure(audit_message_transcriptome.get('audit_category', ''), f'{detail} {audit_message_transcriptome.get("audit_description", "")}', level=audit_message_transcriptome.get('audit_level', ''))

    # Audit 2: if there are genome based analysis files missing genome references
    if files_missing_genome:
        files_missing_genome = join_obj_paths(data_object_paths=files_missing_genome)
        detail = (
            f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} '
            f'has file(s) with no genome `reference_files`: {files_missing_genome}.'
        )
        yield AuditFailure(audit_message_genome.get('audit_category', ''), f'{detail} {audit_message_genome.get("audit_description", "")}', level=audit_message_genome.get('audit_level', ''))

    # Audit 3: if there are transcriptome based analysis tabular files missing transcriptome references
    if tabular_files_missing_transcriptome:
        tabular_files_missing_transcriptome = join_obj_paths(data_object_paths=tabular_files_missing_transcriptome)
        detail = (
            f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} '
            f'has tabular file(s) with no transcriptome `reference_files`: {tabular_files_missing_transcriptome}.'
        )
        yield AuditFailure(audit_message_transcriptome_tabular.get('audit_category', ''), f'{detail} {audit_message_transcriptome_tabular.get("audit_description", "")}', level=audit_message_transcriptome_tabular.get('audit_level', ''))

    # Audit 4: if there are genome based analysis files missing genome references
    if tabular_files_missing_genome:
        tabular_files_missing_genome = join_obj_paths(data_object_paths=tabular_files_missing_genome)
        detail = (
            f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} '
            f'has tabular file(s) with no genome `reference_files`: {tabular_files_missing_genome}.'
        )
        yield AuditFailure(audit_message_genome_tabular.get('audit_category', ''), f'{detail} {audit_message_genome_tabular.get("audit_description", "")}', level=audit_message_genome_tabular.get('audit_level', ''))


# igvfd/audit/file_set.py:audit_anvil_file_fileset_mismatch @ cb8fb4a
def audit_anvil_file_fileset_mismatch(value, system):
    '''
    [
        {
            "audit_description": "All files linked to file sets that are previously submitted to AnVIL should have `anvil_url`.",
            "audit_category": "inconsistent AnVIL status",
            "audit_level": "INTERNAL_ACTION"
        },
        {
            "audit_description": "File sets with files having `anvil_url` should have been submitted to AnVIL.",
            "audit_category": "inconsistent AnVIL status",
            "audit_level": "INTERNAL_ACTION"
        }
    ]
    '''
    object_type = space_in_words(value['@type'][0]).capitalize()
    audit_msg_missed_files = get_audit_message(audit_anvil_file_fileset_mismatch, index=0)
    audit_msg_missed_fileset = get_audit_message(audit_anvil_file_fileset_mismatch, index=1)
    fileset_on_anvil = value.get('is_on_anvil', False)
    files_on_anvil = []
    linked_active_files = []

    # Compute how many ACTIVE files have ANVIL urls
    for file in value.get('files', []):
        file_object = system.get('request').embed(file + '@@object?skip_calculated=true')
        if file_object.get('status') in ['in progress', 'released']:
            linked_active_files.append(file)
            if file_object.get('anvil_url', ''):
                files_on_anvil.append(file)

    # If files are on AnVIL but the linked file set is not
    # Should not happen, but could miss CuratedSet due to how CLS is setup
    if files_on_anvil and not fileset_on_anvil:
        files_on_anvil_paths = ', '.join([audit_link(path_to_text(file), file) for file in files_on_anvil])
        detail = (
            f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} '
            f'links to file(s) {files_on_anvil_paths} with `anvil_url`, but the file set is not marked as submitted to AnVIL.'
        )
        yield AuditFailure(audit_msg_missed_fileset.get('audit_category', ''), f'{detail} {audit_msg_missed_fileset.get("audit_description", "")}', level=audit_msg_missed_fileset.get('audit_level', ''))

    # If file set is on AnVIL but some of its files are not (updates, corrections, etc.)
    if fileset_on_anvil and linked_active_files:
        mismatched_files = list(set(linked_active_files) - set(files_on_anvil))
        if mismatched_files:
            mismatched_files_paths = ', '.join([audit_link(path_to_text(file), file) for file in mismatched_files])
            detail = (
                f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} '
                f'is marked as submitted to AnVIL, but linked files {mismatched_files_paths} do not have `anvil_url`.'
            )
            yield AuditFailure(audit_msg_missed_files.get('audit_category', ''), f'{detail} {audit_msg_missed_files.get("audit_description", "")}', level=audit_msg_missed_files.get('audit_level', ''))


# igvfd/audit/file_set.py:audit_preferred_assay_title @ cb8fb4a
def audit_preferred_assay_title(value, system):
    '''
    [
        {
            "audit_description": "File sets are expected to specify appropriate preferred assay titles for their respective assay term(s).",
            "audit_category": "inconsistent preferred assay titles",
            "audit_level": "ERROR"
        }
    ]
    '''
    object_type = space_in_words(value['@type'][0]).capitalize()
    audit_message_inconsistent = get_audit_message(audit_preferred_assay_title, index=0)

    # Handle both single assay_term and multiple assay_terms (ModelSet)
    assay_term = value.get('assay_term', '')
    assay_terms = value.get('assay_terms', [])

    if not assay_term and not assay_terms:
        return

    all_valid_titles = set()
    if assay_term:
        # CuratedSet case: single assay_term
        assay_object = system.get('request').embed(assay_term, '@@object?skip_calculated=true')
        all_valid_titles = set(assay_object.get('preferred_assay_titles', []))
    else:
        # ModelSet case: multiple assay_terms
        for assay_term in assay_terms:
            assay_object = system.get('request').embed(assay_term, '@@object?skip_calculated=true')
            all_valid_titles.update(assay_object.get('preferred_assay_titles', []))

    assay_titles = value.get('assay_titles', [])
    preferred_assay_titles = value.get('preferred_assay_titles', [])

    if preferred_assay_titles and not all_valid_titles:
        assay_desc = '`assay_term`' if assay_term else '`assay_terms`'
        detail = (
            f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} has '
            f'`preferred_assay_titles` ({", ".join(preferred_assay_titles)}), but the associated {assay_desc} '
            f'{"has" if assay_term else "have"} no `preferred_assay_titles` to validate against.'
        )
        yield AuditFailure(
            audit_message_inconsistent.get('audit_category', ''),
            f'{detail} {audit_message_inconsistent.get("audit_description", "")}',
            level=audit_message_inconsistent.get('audit_level', '')
        )
    elif preferred_assay_titles and not any(title in all_valid_titles for title in preferred_assay_titles):
        detail = (
            f'{object_type} {audit_link(path_to_text(value["@id"]), value["@id"])} has '
            f'`assay_titles` {", ".join(assay_titles)}, but none of its `preferred_assay_titles` values '
            f'({", ".join(preferred_assay_titles)}) are valid. Expected one of: {", ".join(sorted(all_valid_titles))}.'
        )
        yield AuditFailure(
            audit_message_inconsistent.get('audit_category', ''),
            f'{detail} {audit_message_inconsistent.get("audit_description", "")}',
            level=audit_message_inconsistent.get('audit_level', '')
        )


