# igvfd/audit/measurement_set.py:audit_inconsistent_crispr_screen_biometric @ cb8fb4a
def audit_inconsistent_crispr_screen_biometric(value, system):
    '''
    [
        {
            "audit_description": "Measurement sets from CRISPR screen assays are expected to specify a `crispr_screen_biometric` consistent with the screen phenotype: Proliferation CRISPR screen (cell population proliferation), Migration CRISPR screen (cell migration), in vitro CRISPR screen using flow cytometry (protein abundance or LDL-C uptake), in vitro or in vivo CRISPR screen using single-cell RNA-seq (gene expression), or in vitro CRISPR screen using single-nucleus ATAC-seq (chromatin accessibility).",
            "audit_category": "inconsistent crispr screen biometric",
            "audit_level": "NOT_COMPLIANT"
        }
    ]
    '''
    if not is_crispr_screen_measurement_set(value):
        return
    crispr_screen_biometric = value.get('crispr_screen_biometric')
    if not crispr_screen_biometric:
        return
    biometric_term_names = {
        'GO:0008283': 'cell population proliferation',
        'GO:0016477': 'cell migration',
        'BAO:0040014': 'protein abundance method',
        'NTR:0001118': 'LDL-C uptake',
        'GO:0010467': 'gene expression',
        'BAO:0040027': 'chromatin accessibility method',  # BAO official term is misspelled.
    }
    expected_biometric = {
        'Proliferation CRISPR screen': {'GO:0008283'},
        'Migration CRISPR screen': {'GO:0016477'},
        '/assay-terms/OBI_0003661/': {'BAO:0040014', 'NTR:0001118'},  # in vitro CRISPR screen using flow cytometry
        '/assay-terms/OBI_0003660/': {'GO:0010467'},  # in vitro CRISPR screen using single-cell RNA-seq
        '/assay-terms/NTR_0001101/': {'GO:0010467'},  # in vivo CRISPR screen using single cell RNA-seq
        '/assay-terms/NTR_0000798/': {'BAO:0040027'},  # in vitro CRISPR screen using single-nucleus ATAC-seq
    }
    preferred_assay_title = value.get('preferred_assay_titles', [None])[0]
    assay_term = value.get('assay_term', '')
    if preferred_assay_title in expected_biometric:
        expected_term_ids = expected_biometric[preferred_assay_title]
        screen_phrase = f'{preferred_assay_title} measurement sets'
    elif assay_term in expected_biometric:
        expected_term_ids = expected_biometric[assay_term]
        assay_object = system.get('request').embed(assay_term, '@@object?skip_calculated=true')
        screen_phrase = f'{assay_object.get("term_name", "")} measurement sets'
    else:
        return
    audit_message = get_audit_message(audit_inconsistent_crispr_screen_biometric)
    biometric_object = system.get('request').embed(
        crispr_screen_biometric,
        '@@object?skip_calculated=true'
    )
    biometric_term_id = biometric_object.get('term_id', '')
    if biometric_term_id in expected_term_ids:
        return
    expected_phrases = []
    for term_id in sorted(expected_term_ids):
        phenotype_term = f'/phenotype-terms/{term_id.replace(":", "_")}/'
        expected_phrases.append(
            f'{audit_link(path_to_text(phenotype_term), phenotype_term)} '
            f'({biometric_term_names[term_id]})'
        )
    expected_phrase = ', '.join(expected_phrases)
    detail = (
        f'Measurement set {audit_link(path_to_text(value["@id"]), value["@id"])} '
        f'has `crispr_screen_biometric` {audit_link(path_to_text(crispr_screen_biometric), crispr_screen_biometric)} '
        f'({biometric_object.get("term_name", "")}), but {screen_phrase} '
        f'are expected to use one of: {expected_phrase}.'
    )
    yield AuditFailure(
        audit_message.get('audit_category', ''),
        f'{detail} {audit_message.get("audit_description", "")}',
        level=audit_message.get('audit_level', '')
    )


# igvfd/audit/measurement_set.py:audit_CRISPR_screen_lacking_modifications @ cb8fb4a
def audit_CRISPR_screen_lacking_modifications(value, system):
    '''
    [
        {
            "audit_description": "Measurement sets from CRISPR-based assays are expected to have a modification specified on their samples, unless the measurement set is a wildtype control.",
            "audit_category": "missing modification",
            "audit_level": "NOT_COMPLIANT"
        }
    ]
    '''
    audit_message = get_audit_message(audit_CRISPR_screen_lacking_modifications)
    if not is_crispr_screen_measurement_set(value):
        return
    if 'wildtype' in value.get('control_types', []):
        return
    samples = value.get('samples', [])
    bad_samples = []
    for sample in samples:
        sample_object = system.get('request').embed(sample, '@@object')
        if 'modifications' not in sample_object:
            bad_samples.append(sample)
    if bad_samples != []:
        samples_to_link = [audit_link(path_to_text(bad_sample), bad_sample) for bad_sample in bad_samples]
        sample_detail = ', '.join(samples_to_link)
        detail = (
            f'Measurement set {audit_link(path_to_text(value["@id"]), value["@id"])} is '
            f'a CRISPR screen assay but has no specified `modifications` on its `samples`: {sample_detail}.'
        )
        yield AuditFailure(audit_message.get('audit_category', ''), f'{detail} {audit_message.get("audit_description", "")}', level=audit_message.get('audit_level', ''))


# igvfd/audit/measurement_set.py:audit_missing_institutional_certification @ cb8fb4a
def audit_missing_institutional_certification(value, system):
    '''
    [
        {
            "audit_description": "Measurement sets for mapping assays or controlled access characterization assays involving samples with a human origin are expected to link to the relevant institutional certificates.",
            "audit_category": "missing NIH certification",
            "audit_level": "NOT_COMPLIANT"
        }
    ]
    '''
    audit_message = get_audit_message(audit_missing_institutional_certification)
    # Only audit Measurement Sets with at least one human sample.
    donors = value.get('donors', [])
    taxa = set()
    for donor in donors:
        donor_obj = system.get('request').embed(donor, '@@object?skip_calculated=true')
        taxa.add(donor_obj.get('taxa', ''))
    if 'Homo sapiens' not in taxa:
        return

    # Characterization assays do not need to be audited if they do not have controlled access data.
    characterization_assays = [
        'OBI:0003133',  # cas mediated mutagenesis
        'OBI:0003659',  # in vitro CRISPR screen assay
        'OBI:0003661',  # in vitro CRISPR screen using flow cytometry
        'OBI:0003660',  # in vitro CRISPR screen using single-cell RNA-seq
        'NTR:0000798',  # in vitro CRISPR screen using single-nucleus ATAC-seq
        'NTR:0001101',  # in vivo CRISPR screen using single cell RNA-seq
        'OBI:0000916',  # flow cytometry assay
        'OBI:0000185',  # imaging assay
        'NTR:0001096',  # varACCESS
        'OBI:0002675',  # massively parallel reporter assay,
        'OBI:0000288',  # protein-protein interaction detection assay,
        'OBI:0002041',  # self-transcribing active regulatory region sequencing assay,
        'OBI:0002082',  # reporter gene assay (for LABEL-seq)
        'NTR:0001094',  # yeast-based functional complementation assay
        'NTR:0001112',  # LABEL-seq
        'NTR:0001113',  # Immune-SGE
        'NTR:0001114',  # VAMP-seq
        'NTR:0001115',  # SGE
        'NTR:0001116'   # VAMP-seq (MultiSTEP)
    ]
    assay_term = value.get('assay_term', '')
    assay_object = system.get('request').embed(assay_term, '@@object?skip_calculated=true')
    assay_term_id = assay_object.get('term_id', '')
    files = [system.get('request').embed(file, '@@object?skip_calculated=true') for file in value.get('files', '')]
    if assay_term_id in characterization_assays and not (any([file.get('controlled_access') for file in files])):
        return

    lab = value.get('lab', '')
    award = value.get('award', '')
    samples = value.get('samples', [])

    sample_objects_to_check = []
    for sample in samples:
        sample_object = system.get('request').embed(sample, '@@object')
        if 'MultiplexedSample' in sample_object['@type']:
            multiplexed_sample_id = sample_object['@id']
            multiplexed_phrase = f' that is multiplexed in {audit_link(path_to_text(multiplexed_sample_id), multiplexed_sample_id)}'
            for mux_sample in sample_object['multiplexed_samples']:
                mux_sample_object = system.get('request').embed(mux_sample, '@@object')
                if any(donor.startswith('/human-donors/') for donor in mux_sample_object.get('donors', [])):
                    sample_objects_to_check.append((mux_sample_object, multiplexed_phrase))
        else:
            sample_objects_to_check.append((sample_object, ''))

    for sample_tuple in sample_objects_to_check:
        sample = sample_tuple[0]
        multiplexed_phrase = sample_tuple[1]
        nic_labs = []
        nic_awards = []
        for nic in sample.get('institutional_certificates', []):
            nic_object = system.get('request').embed(nic, '@@object?skip_calculated=true')
            nic_labs.append(nic_object.get('lab', ''))
            if 'partner_labs' in nic_object:
                for partner in nic_object.get('partner_labs', []):
                    nic_labs.append(partner)
            nic_awards.append(nic_object.get('award', ''))
            if 'partner_awards' in nic_object:
                for partner in nic_object.get('partner_awards', []):
                    nic_awards.append(partner)
        if lab not in nic_labs or award not in nic_awards:
            detail = (
                f'Measurement set {audit_link(path_to_text(value["@id"]), value["@id"])} has '
                f'a sample {audit_link(path_to_text(sample["@id"]), sample["@id"])}{multiplexed_phrase} '
                f'that lacks any `institutional_certificates` issued to the lab '
                f'that submitted this file set or to a partner lab/award of the submitting lab.'
            )
            yield AuditFailure(audit_message.get('audit_category', ''), f'{detail} {audit_message.get("audit_description", "")}', level=audit_message.get('audit_level', ''))


# igvfd/audit/measurement_set.py:audit_missing_auxiliary_set_link @ cb8fb4a
def audit_missing_auxiliary_set_link(value, system):
    '''
    [
        {
            "audit_description": "Measurement sets are expected to link to auxiliary sets if they share the same sample.",
            "audit_category": "missing auxiliary set link",
            "audit_level": "ERROR"
        }
    ]
    '''
    audit_message = get_audit_message(audit_missing_auxiliary_set_link)
    samples = value.get('samples', [])
    auxiliary_sets = value.get('auxiliary_sets', [])
    for sample in samples:
        sample_object = system.get('request').embed(sample, '@@object')
        for file_set in sample_object.get('file_sets', []):
            if file_set.startswith('/auxiliary-sets/') and file_set not in auxiliary_sets:
                auxiliary_set_object = system.get('request').embed(file_set, '@@object?skip_calculated=true')
                if auxiliary_set_object.get('status', '') in ['in progress', 'released', 'archived']:
                    detail = (
                        f'Measurement set {audit_link(path_to_text(value["@id"]), value["@id"])} links '
                        f'to sample {audit_link(path_to_text(sample), sample)} which links to auxiliary set '
                        f'{audit_link(path_to_text(file_set), file_set)} but is not in its `auxiliary_sets`.'
                    )
                    yield AuditFailure(audit_message.get('audit_category', ''), f'{detail} {audit_message.get("audit_description", "")}', level=audit_message.get('audit_level', ''))


# igvfd/audit/measurement_set.py:audit_targeted_genes @ cb8fb4a
def audit_targeted_genes(value, system):
    '''
    [
        {
            "audit_description": "Transcription factor ChIP-seq, CRISPR screens with protein abundance biometrics, MORF screen, VAMP-seq, and VAMP-seq (MultiSTEP) assays are expected to specify targeted gene(s).",
            "audit_category": "missing targeted genes",
            "audit_level": "NOT_COMPLIANT"
        },
        {
            "audit_description": "Only transcription factor ChIP-seq, CRISPR screens with protein abundance biometrics, MORF screen, VAMP-seq, and VAMP-seq (MultiSTEP) assays are expected to specify targeted gene(s).",
            "audit_category": "unexpected targeted genes",
            "audit_level": "ERROR"
        }
    ]
    '''
    audit_message_missing = get_audit_message(audit_targeted_genes, index=0)
    audit_message_unexpected = get_audit_message(audit_targeted_genes, index=1)
    preferred_assay_titles = value.get('preferred_assay_titles', [])
    targeted_genes = value.get('targeted_genes', '')
    control_types = value.get('control_types', [])
    exempted_control_types = {
        'baseline',
        'untransfected',
        'unsorted FACS input'
    }
    expecting_targeted_genes_by_preferred_assay_title = ['MORF screen',
                                                         'TF ChIP-seq',
                                                         'VAMP-seq',
                                                         'VAMP-seq (MultiSTEP)'
                                                         ]
    expects_targeted_genes = (
        any(title in expecting_targeted_genes_by_preferred_assay_title for title in preferred_assay_titles)
        or is_protein_abundance_biometric(value, system)
    )
    has_biomarker_genes = False
    for sample in value.get('samples', []):
        sample_object = system.get('request').embed(sample, '@@object')
        for biomarker in sample_object.get('biomarkers', []):
            biomarker_object = system.get('request').embed(
                biomarker,
                '@@object?skip_calculated=true'
            )
            if biomarker_object.get('gene'):
                has_biomarker_genes = True
                break
        if has_biomarker_genes:
            break
    if (
        not targeted_genes
        and not has_biomarker_genes
        and expects_targeted_genes
        and not any(control_type in exempted_control_types for control_type in control_types)
    ):
        detail = (
            f'Measurement set {audit_link(path_to_text(value["@id"]), value["@id"])} '
            f'has no `targeted_genes`.'
        )
        yield AuditFailure(
            audit_message_missing.get('audit_category', ''),
            f'{detail} {audit_message_missing.get("audit_description", "")}',
            level=audit_message_missing.get('audit_level', '')
        )
    if targeted_genes and not expects_targeted_genes:
        detail = (
            f'Measurement set {audit_link(path_to_text(value["@id"]), value["@id"])} '
            f'has `targeted_genes`.'
        )
        yield AuditFailure(audit_message_unexpected.get('audit_category', ''), f'{detail} {audit_message_unexpected.get("audit_description", "")}', level=audit_message_unexpected.get('audit_level', ''))


